//! The generated invariant check (story `generated-invariant-check`).
//!
//! Every generated entity data type whose entity declares `invariants:` carries
//! `broken_invariant(&self) -> Option<&'static str>`: the first declared invariant the value
//! breaks, named by the text the specification declares, or `None`. The fixture below declares
//! every predicate form the compiler admits in an entity invariant; the harness — outside the
//! generated bytes, built with `-D warnings` — holds one value that satisfies all of them, one
//! value per invariant that breaks it and nothing declared before it, and the values whose reads
//! are absent, which decide nothing. The test names each expected invariant by its index in the
//! compiled model, so the harness cannot agree with a wrong rendering of a statement.

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};

use ess_compiler::{resolve::compile, source::SourceMap, EssIr};
use ess_domain::{spec::RawSpecFile, system::Source, Specification};
use ess_synth::{synthesize_for, Synthesis, Target};

/// One entity whose invariants use every form: a constant, identity, integer, decimal, struct
/// member, field against field, instant against instant and against a literal, text order, enum
/// equality, `any_of`, `none_of`, the three string operators, both case-insensitive operators,
/// text length, Boolean equality, truthiness of a number and of a Boolean, `all`/`any`/`not`,
/// `Duration`, `Uuid` and `Bytes` equality, `defined` over an `Optional` aggregate and over
/// `Json`, an `Optional` scalar, a list's count and position, `forall` and `exists` over a list
/// and a map, a nested quantifier reading both binders, and `state`. A second entity declares
/// `never`.
const MODEL: &str = r#"format: ess/16
system: demo
version: v1
domain: demo.ledger
types:
  - {name: demo.ledger.Code, kind: newtype, of: String}
  - {name: demo.ledger.Tier, kind: enum, variants: [Basic, Premium, Trial, Retired]}
  - name: demo.ledger.Money
    kind: struct
    fields:
      - {name: amount, type: Decimal}
  - name: demo.ledger.Window
    kind: struct
    fields:
      - {name: opens, type: Timestamp}
      - {name: closes, type: Timestamp}
      - {name: low, type: Integer}
      - {name: high, type: Integer}
  - name: demo.ledger.Line
    kind: struct
    fields:
      - {name: qty, type: Integer}
      - {name: label, type: Optional<String>}
  - name: demo.ledger.Extra
    kind: struct
    fields:
      - {name: level, type: Integer}
entities:
  - name: demo.ledger.Account
    identity: {name: id, type: String}
    fields:
      - {name: count, type: Integer}
      - {name: ratio, type: Decimal}
      - {name: total, type: demo.ledger.Money}
      - {name: active, type: Boolean}
      - {name: flag, type: Boolean}
      - {name: title, type: String}
      - {name: code, type: demo.ledger.Code}
      - {name: region, type: String}
      - {name: currency, type: String}
      - {name: tier, type: demo.ledger.Tier}
      - {name: starts_at, type: Timestamp}
      - {name: window, type: demo.ledger.Window}
      - {name: grace, type: Duration}
      - {name: ref, type: Uuid}
      - {name: blob, type: Bytes}
      - {name: note, type: Optional<String>}
      - {name: extra, type: Optional<demo.ledger.Extra>}
      - {name: payload, type: Optional<Json>}
      - {name: lines, type: List<demo.ledger.Line>}
      - {name: tags, type: "Map<String, Integer>"}
    invariants:
      - always
      - id != ""
      - count >= 0
      - ratio <= 1.5
      - ratio != 0.25
      - total.amount > 0
      - window.low <= window.high
      - window.opens < window.closes
      - starts_at >= "2020-01-01T00:00:00Z"
      - code >= B
      - tier != Retired
      - tier: {any_of: [Basic, Premium]}
      - count: {any_of: [0, 1, 2, 3]}
      - code: {none_of: [C-0]}
      - title: {starts_with: T}
      - code: {ends_with: "1"}
      - title: {contains: i}
      - region: {in_ignore_case: [eu, us]}
      - currency: {equals_ignore_case: eur}
      - title.count <= 8
      - active == true
      - count: {truthy: true}
      - any: [flag, window.low == 0]
      - all: [{not: grace == PT0S}, ref != 00000000-0000-0000-0000-000000000000]
      - blob != AAAA
      - any: [{not: defined(extra)}, extra.level >= 1]
      - not defined(payload)
      - note.count <= 5
      - lines.count >= 1
      - lines.0.qty <= 100
      - forall: {in: lines, as: line, that: line.qty > 0}
      - forall: {in: lines, as: line, that: {any: [not defined(line.label), line.label.count > 0]}}
      - tags.count <= 3
      - exists: {in: tags, as: tag, that: tag >= 10}
      - forall: {in: lines, as: line, that: {exists: {in: tags, as: tag, that: tag >= line.qty}}}
      - any: [state == Open, window.high < 100]
    lifecycle:
      initial: Open
      states: [Open]
      terminal: [Open]
  - name: demo.ledger.Seal
    identity: {name: id, type: String}
    invariants:
      - never
    lifecycle:
      initial: Sealed
      states: [Sealed]
      terminal: [Sealed]
"#;

/// The harness: each line is `<expected> <actual>`, where `<expected>` is the index of the
/// invariant the value must be refused by, or `none`, and `<actual>` is what
/// `broken_invariant()` answered.
const HARNESS: &str = r#"use std::collections::BTreeMap;

use demo_types::json::Value;
use demo_types::ledger::{AccountData, Code, Extra, Line, Money, SealData, Tier, Window};
use demo_types::primitives::{Decimal, Duration, Timestamp, Uuid};

fn text(value: &str) -> String {
    value.to_owned()
}

/// Satisfies every invariant. Its instants are ordered only by the instant they name: by their
/// bytes `opens` sorts after `closes`, and `starts_at` sorts before its bound.
fn base() -> AccountData {
    AccountData {
        id: text("a-1"),
        count: 1,
        ratio: Decimal(text("1.50")),
        total: Money { amount: Decimal(text("10.00")) },
        active: true,
        flag: true,
        title: text("Title"),
        code: Code(text("C-1")),
        region: text("EU"),
        currency: text("EUR"),
        tier: Tier::Basic,
        starts_at: Timestamp(text("2020-01-01T01:30:00+01:00")),
        window: Window {
            opens: Timestamp(text("2026-01-01T01:30:00+02:00")),
            closes: Timestamp(text("2026-01-01T00:00:00Z")),
            low: 1,
            high: 10,
        },
        grace: Duration(text("PT5M")),
        r#ref: Uuid(text("6f1c0f6e-5e8a-4c3f-9f7d-2b1a0c9e8d7f")),
        blob: vec![1, 2, 3],
        note: None,
        extra: None,
        payload: None,
        lines: vec![
            Line { qty: 1, label: None },
            Line { qty: 2, label: Some(text("second")) },
        ],
        tags: BTreeMap::from([(text("a"), 10)]),
    }
}

/// The shared evaluator's readings the cases above do not reach one by one: base64 padding,
/// exact decimal order, and instants that name no day.
fn evaluator() {
    use demo_types::primitives::invariant::{self as iv, Fact, Number, Op};
    let text = |value: &str| Fact::Text(value.to_owned().into());
    assert_eq!(Fact::bytes(&[0]), text("AA=="));
    assert_eq!(Fact::bytes(&[0xfb, 0xff]), text("+/8="));
    assert_eq!(Fact::bytes(&[]), text(""));
    let number = |value: &str| Number::parse(value).expect("a number");
    assert_eq!(number("1.50"), number("15e-1"));
    assert_eq!(number("-0.0"), number("0"));
    assert!(number("-2") < number("-1.5"));
    assert!(number("0.001") < number("0.01"));
    assert!(number("99.999") < number("100"));
    assert!(number("-0.5") < number("0"));
    assert_eq!(Number::parse("1.2.3"), None);
    assert_eq!(Number::parse("e5"), None);
    assert_eq!(Fact::number("x"), None);
    let instant = |left: &str, op: Op, right: &str| {
        iv::compare(Some(Fact::text(left)), op, Some(Fact::text(right)), true, true)
    };
    assert_eq!(instant("2020-02-29T00:00:00Z", Op::Lt, "2020-03-01T00:00:00Z"), Some(true));
    assert_eq!(instant("2021-02-29T00:00:00Z", Op::Lt, "2021-03-01T00:00:00Z"), None);
    assert_eq!(instant("2020-01-01T00:00:00.5Z", Op::Gt, "2020-01-01T00:00:00Z"), Some(true));
    assert_eq!(instant("2020-01-01T00:00:00+00:00", Op::Eq, "2020-01-01T00:00:00Z"), Some(true));
    assert_eq!(instant("soon", Op::Eq, "soon"), Some(true));
    assert_eq!(instant("1969-12-31T23:59:59Z", Op::Lt, "1970-01-01T00:00:00Z"), Some(true));
}

fn with(change: impl FnOnce(&mut AccountData)) -> AccountData {
    let mut value = base();
    change(&mut value);
    value
}

fn main() {
    let cases: Vec<(&str, AccountData)> = vec![
        ("none", base()),
        ("1", with(|v| v.id = text(""))),
        ("2", with(|v| v.count = -1)),
        ("3", with(|v| v.ratio = Decimal(text("1.50001")))),
        ("none", with(|v| v.ratio = Decimal(text("15e-1")))),
        ("4", with(|v| v.ratio = Decimal(text("0.250")))),
        ("5", with(|v| v.total.amount = Decimal(text("0.00")))),
        ("5", with(|v| v.total.amount = Decimal(text("-3")))),
        ("6", with(|v| { v.window.low = 5; v.window.high = 4; })),
        ("7", with(|v| v.window.closes = Timestamp(text("2025-12-31T23:30:00Z")))),
        ("8", with(|v| v.starts_at = Timestamp(text("2020-01-01T00:30:00+01:00")))),
        ("9", with(|v| v.code = Code(text("A-1")))),
        ("10", with(|v| v.tier = Tier::Retired)),
        ("11", with(|v| v.tier = Tier::Trial)),
        ("none", with(|v| v.tier = Tier::Premium)),
        ("12", with(|v| v.count = 7)),
        ("13", with(|v| v.code = Code(text("C-0")))),
        ("14", with(|v| v.title = text("xi"))),
        ("15", with(|v| v.code = Code(text("C-2")))),
        ("16", with(|v| v.title = text("Tops"))),
        ("17", with(|v| v.region = text("apac"))),
        ("none", with(|v| v.region = text("Us"))),
        ("18", with(|v| v.currency = text("USD"))),
        ("19", with(|v| v.title = text("Titanic!!"))),
        ("none", with(|v| v.title = text("Tiéééééé"))),
        ("20", with(|v| v.active = false)),
        ("21", with(|v| v.count = 0)),
        ("22", with(|v| v.flag = false)),
        ("none", with(|v| { v.flag = false; v.window.low = 0; })),
        ("23", with(|v| v.grace = Duration(text("PT0S")))),
        ("23", with(|v| v.r#ref = Uuid(text("00000000-0000-0000-0000-000000000000")))),
        ("24", with(|v| v.blob = vec![0, 0, 0])),
        ("25", with(|v| v.extra = Some(Extra { level: 0 }))),
        ("none", with(|v| v.extra = Some(Extra { level: 2 }))),
        ("26", with(|v| v.payload = Some(Value::Bool(true)))),
        ("27", with(|v| v.note = Some(text("toolong")))),
        ("none", with(|v| v.note = Some(text("short")))),
        ("28", with(|v| v.lines.clear())),
        ("29", with(|v| v.lines[0].qty = 101)),
        ("30", with(|v| v.lines[1].qty = 0)),
        ("31", with(|v| v.lines[1].label = Some(text("")))),
        ("32", with(|v| {
            v.tags.insert(text("b"), 11);
            v.tags.insert(text("c"), 12);
            v.tags.insert(text("d"), 13);
        })),
        ("33", with(|v| v.tags = BTreeMap::from([(text("a"), 1)]))),
        ("33", with(|v| v.tags.clear())),
        ("34", with(|v| v.lines[1].qty = 11)),
        ("none", with(|v| v.window.high = 200)),
        ("2", with(|v| { v.count = -1; v.lines[1].qty = 0; })),
    ];
    for (expected, value) in cases {
        println!("{expected} {:?}", value.broken_invariant());
    }
    evaluator();
    println!("seal {:?}", SealData { id: text("s-1") }.broken_invariant());
}
"#;

fn ir(source: &str) -> EssIr {
    let spec = Specification::assemble([(
        Source::new("spec.yaml"),
        RawSpecFile::parse(source).expect("well formed"),
    )])
    .unwrap_or_else(|errors| panic!("validates: {errors}"));
    let mut sources = SourceMap::new();
    sources.insert("spec.yaml", source);
    compile(&spec, &sources).unwrap_or_else(|errors| panic!("compiles: {errors}"))
}

fn scratch(label: &str) -> PathBuf {
    Path::new(env!("CARGO_TARGET_TMPDIR")).join(format!("invariant-check-{label}"))
}

fn write(synthesis: &Synthesis, directory: &Path) {
    let _ = std::fs::remove_dir_all(directory);
    for (relative, artifact) in &synthesis.artifacts {
        let destination = directory.join(relative);
        std::fs::create_dir_all(destination.parent().unwrap()).unwrap();
        std::fs::write(&destination, &artifact.contents).unwrap();
    }
}

/// Cargo inside the harness, with every warning an error: generated code that warns is an emitter
/// defect a consumer's own `-D warnings` build would inherit.
fn cargo(directory: &Path, arguments: &[&str]) -> Output {
    let output = Command::new(std::env::var_os("CARGO").expect("Cargo supplies its executable"))
        .args(arguments)
        .current_dir(directory)
        .env_remove("CARGO_TARGET_DIR")
        .env_remove("CARGO_ENCODED_RUSTFLAGS")
        .env("RUSTFLAGS", "-D warnings")
        .output()
        .expect("cargo runs");
    eprintln!(
        "cargo {arguments:?} in {}\n{}{}",
        directory.display(),
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    output
}

#[test]
fn every_invariant_form_is_checked_by_the_generated_data_type() {
    let ir = ir(MODEL);
    let account = ir
        .entities()
        .values()
        .find(|entity| entity.name.to_string() == "demo.ledger.Account")
        .expect("the fixture declares the account");
    let statements: Vec<String> = account
        .invariants
        .iter()
        .map(|invariant| invariant.statement.clone())
        .collect();
    assert_eq!(statements.len(), 36, "{statements:#?}");
    let synthesis = synthesize_for(&ir, Target::Rust).expect("the fixture synthesizes");

    let root = scratch("harness");
    let generated = root.join("generated");
    write(&synthesis, &generated);
    let harness = root.join("harness");
    std::fs::create_dir_all(harness.join("src")).unwrap();
    std::fs::write(
        harness.join("Cargo.toml"),
        "[package]\nname = \"invariant-harness\"\nversion = \"0.0.0\"\nedition = \"2021\"\n\n\
         [dependencies]\ndemo-types = { path = \"../generated/crates/demo-types\" }\n\n\
         [workspace]\n",
    )
    .unwrap();
    std::fs::write(harness.join("src/main.rs"), HARNESS).unwrap();
    let target = root.join("target");
    let run = cargo(
        &harness,
        &[
            "run",
            "--offline",
            "--quiet",
            "--target-dir",
            target.to_str().unwrap(),
        ],
    );
    let stdout = String::from_utf8_lossy(&run.stdout).into_owned();
    let _ = std::fs::remove_dir_all(&root);
    assert!(run.status.success(), "the harness builds and runs");

    let mut lines = stdout.lines().collect::<Vec<_>>();
    assert_eq!(lines.pop(), Some("seal Some(\"never\")"), "{stdout}");
    let mut broken = BTreeSet::new();
    for line in &lines {
        let (expected, actual) = line.split_once(' ').expect("`<expected> <actual>`");
        let want = if expected == "none" {
            "None".to_owned()
        } else {
            let index: usize = expected.parse().expect("an invariant index");
            broken.insert(index);
            format!("Some({:?})", statements[index])
        };
        assert_eq!(actual, want, "case `{line}`");
    }
    let every: BTreeSet<usize> = (1..statements.len() - 1).collect();
    assert_eq!(
        broken, every,
        "every invariant but `always` and the state-reading one is broken by some case"
    );
}

/// The fixture's entity without its invariants: nothing about invariants reaches the emitted
/// workspace, so a model that declares none keeps every byte it had.
#[test]
fn a_model_without_invariants_emits_no_check() {
    let bare = MODEL
        .split("    invariants:\n")
        .enumerate()
        .map(|(position, part)| {
            if position == 0 {
                part.to_owned()
            } else {
                part.split_once("    lifecycle:\n")
                    .map(|(_, rest)| format!("    lifecycle:\n{rest}"))
                    .expect("each invariant list is followed by a lifecycle")
            }
        })
        .collect::<String>();
    let ir = ir(&bare);
    assert!(ir
        .entities()
        .values()
        .all(|entity| entity.invariants.is_empty()));
    let synthesis = synthesize_for(&ir, Target::Rust).expect("the fixture synthesizes");
    for (path, artifact) in &synthesis.artifacts {
        assert!(
            !artifact.contents.contains("broken_invariant")
                && !artifact.contents.contains("pub mod invariant"),
            "`{path}` carries an invariant check for a model that declares none"
        );
    }
}
